// THE NARRATOR APPEARS IN THE STORY (client 2026-08-26).
//
// The video already has a talking-head avatar, generated by HeyGen from the
// project's uploaded photo. Everywhere else, the people in the b-roll are
// anonymous strangers invented by the image model — so the presenter and the
// story look like they belong to two different videos.
//
// The client's ask: let the avatar's own face turn up as a CHARACTER inside a
// few scenes, "and of course all clip is not related to the avatar and show the
// small count". So this is deliberately a handful of blocks per video, not a
// recurring protagonist.
//
// WHY A SMALL COUNT IS LOAD-BEARING, not just a cost choice:
// sanitizeBasePrompt (planner.ts) exists to STRIP any clause that pins one
// person doing one thing into every frame, because that produced a repetition
// complaint. Marking many blocks would rebuild exactly what that guard tears
// down. A few marked blocks read as the narrator stepping into the story; forty
// read as the same stranger following you around.
//
// Selection is deterministic (no model call): a block qualifies when its
// narration is in the presenter's OWN voice and its planned scene ALREADY has a
// person in it. The second half matters — dropping a face into a shot of a
// receiver on a workbench would just be wrong.
import { sceneHasPerson } from "@/lib/synthetic/clip-motion";
import type { SyntheticBlockType } from "@/lib/types";

// First person singular — the strongest signal that the presenter is speaking
// as themselves rather than narrating.
const FIRST_PERSON_SINGULAR_RE = /\b(i|i'm|i've|i'd|i'll|me|my|myself|mine)\b/i;
// First person plural / inclusive address ("let us be clear about that").
const FIRST_PERSON_PLURAL_RE = /\b(we|we're|we've|we'd|us|our|ours|ourselves|let's)\b/i;
// Direct address to the viewer ("before you price it", "you are standing on").
const DIRECT_ADDRESS_RE = /\b(you|you're|you've|you'd|you'll|your|yours|yourself)\b/i;

// Blocks that ALREADY show the avatar (HeyGen renders the real face) are never
// candidates — the point is to place the face where it is currently absent.
const ELIGIBLE_BLOCK_TYPES: ReadonlySet<string> = new Set(["image", "ai_clip"]);

export interface CharacterCandidate {
  blockType: SyntheticBlockType;
  script: string;
  imagePrompt: string | null;
}

/**
 * How strongly this line is the presenter's own voice. 0 = not personal.
 *
 * Ranked rather than boolean so that when more lines qualify than the cap
 * allows, the most personal ones win instead of merely the earliest.
 */
export function personalVoiceScore(script: string | null | undefined): number {
  const s = (script ?? "").trim();
  if (!s) return 0;
  if (FIRST_PERSON_SINGULAR_RE.test(s)) return 3;
  if (FIRST_PERSON_PLURAL_RE.test(s)) return 2;
  if (DIRECT_ADDRESS_RE.test(s)) return 1;
  return 0;
}

/**
 * Pick the indices whose visual should feature the project's avatar.
 *
 * Greedy by score, then spread: a `minGap` between chosen indices stops the
 * whole allowance being spent inside one paragraph, which is what would make
 * the face read as a recurring character instead of an occasional appearance.
 */
export function selectCharacterBlocks(
  blocks: readonly CharacterCandidate[],
  opts: { max: number; minGap?: number },
): number[] {
  const max = Math.max(0, Math.floor(opts.max));
  if (max === 0 || blocks.length === 0) return [];
  // Default spacing spreads the allowance across the whole video; a floor of 8
  // keeps short videos from clustering two appearances back to back.
  const minGap = opts.minGap ?? Math.max(8, Math.floor(blocks.length / (max + 1)));

  const scored = blocks
    .map((b, index) => ({ index, score: personalVoiceScore(b.script), block: b }))
    .filter(({ block, score }) =>
      score > 0 &&
      ELIGIBLE_BLOCK_TYPES.has(block.blockType) &&
      // The scene must already contain a person for a face to belong in it.
      sceneHasPerson(block.imagePrompt),
    )
    // Strongest voice first; ties broken by position so the result is stable
    // for a given plan rather than dependent on sort implementation.
    .sort((a, b) => b.score - a.score || a.index - b.index);

  const chosen: number[] = [];
  for (const { index } of scored) {
    if (chosen.length >= max) break;
    if (chosen.every((c) => Math.abs(c - index) >= minGap)) chosen.push(index);
  }
  return chosen.sort((a, b) => a - b);
}

/**
 * Wrap a block's scene prompt for a reference-conditioned generation.
 *
 * The reference IMAGE carries the likeness; this text only has to stop the
 * model inventing a second person or turning the shot into a portrait. Keeping
 * it short matters — the scene description is what makes the shot match the
 * narration, and burying it under identity boilerplate would trade one of the
 * client's complaints for another.
 */
export function characterScenePrompt(scenePrompt: string): string {
  return (
    "The person in the supplied reference photograph — the same face, same " +
    "hair, same age — appears in this scene as the person in it. Keep their " +
    "likeness exactly; do not add any other people. This is a candid " +
    "documentary photograph of that moment, NOT a portrait and NOT a posed " +
    "shot: they are doing the thing described, and the scene below is what " +
    "matters most.\n\n" +
    scenePrompt.trim()
  );
}
